using System;
using System.IO;
using System.Linq;
using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;
namespace IanGame.Editor {
public static class SceneArchitectureVerification {
 static LifeWorldController W=>GameContext.Instance.game.world.Host;
 static SceneTransitionService T=>GameContext.Instance.transitions;
 static IEnumerator Wait(){float until=Time.unscaledTime+25;while((T.IsTransitioning||W==null||W.Busy)&&Time.unscaledTime<until)yield return null;if(T.IsTransitioning||W==null||W.Busy)throw new Exception("Room transition timeout / "+T.LastError);yield return null;yield return null;}
 static IEnumerator Go(string id,Action<bool,string> check){var z=T.roomCatalog.rules.Zone(id);check(T.NavigateRoom(id,z.spawn,Vector2.down),"Request room "+id);yield return Wait();check(SceneManager.GetActiveScene().name==T.roomCatalog.Find(id).sceneName&&W.CurrentZone.id==id,"Actual active scene / room "+id);}
 static IEnumerator Shot(string name){Directory.CreateDirectory("Docs/SceneArchitecture/Screenshots");ScreenCapture.CaptureScreenshot("Docs/SceneArchitecture/Screenshots/"+name+".png");yield return null;}
 public static IEnumerator Run(GameManager g,Action<bool,string> check,Action<GameObject,string> audit,string mode){
  check(W.Room!=null&&W.Room.roomId=="family-ian-bedroom","Newborn starts in actual independent Ian bedroom scene");check(!W.Player.MovementAllowed&&!W.Travel("city"),"Newborn movement and outdoor travel remain blocked");var catalog=T.roomCatalog;check(catalog.rooms.Length==16,"Sixteen physical room scenes registered");foreach(var edge in catalog.portals)check(catalog.Find(edge.destinationRoom)!=null&&catalog.portals.Any(p=>p.sourceRoom==edge.destinationRoom&&p.destinationRoom==edge.sourceRoom),"Bidirectional registered destination "+edge.doorId);
  var legacy=g.CaptureState().world;legacy.zone=FamilyLife.Home;legacy.position=new Vector2(-8,4);catalog.Migrate(legacy,19);check(legacy.zone=="family-parents-bedroom"&&legacy.position==new Vector2(0,-1),"Legacy family world coordinates migrate to room-local coordinates");catalog.ToLegacy(legacy);check(legacy.zone==FamilyLife.Home&&legacy.position==new Vector2(-8,4),"Legacy coordinate mapping is reversible without drift");
  g.growth.Restore(new ProgressSnapshot{age=1});check(W.Player.MovementAllowed&&!W.Travel("city"),"Age one walking and independent outdoor gates remain separate");g.growth.Restore(new ProgressSnapshot{age=19});g.clock.realtimeEnabled=false;g.clock.Restore(1,new TimeSnapshot{subDaySeconds=14*3600});var funded=g.stats.Capture();funded.money=1000;g.stats.Restore(funded);check(g.economy.MoveResidence("qa-scene-independence","starter"),"Room fixture uses real paid optional independence");
  if(mode=="sceneDoors"){foreach(var edge in catalog.portals){yield return Go(edge.sourceRoom,check);var w=W;var o=w.objects.First(x=>x.id==edge.doorId);var d=o.GetComponent<WorldDoor>();if(d!=null){d.opens=0;d.closes=24;w.Player.Warp(d.Approach(d.Plane-d.normal));}else w.Player.Warp(o.Point);yield return null;check(w.Use(o),"Real door interaction "+edge.doorId);check(!w.Use(o),"Duplicate interaction rejected "+edge.doorId);yield return Wait();check(W.Room.roomId==edge.destinationRoom,"Door crossed into destination scene "+edge.doorId);var entry=W.GetComponentsInChildren<RoomEntryPoint>().First(p=>p.entryId==edge.destinationEntryId);check(Vector2.Distance(W.Player.Position,entry.transform.position)<.3f&&W.CanControl,"Arrival anchor and controls restored "+edge.doorId+" actual="+W.Player.Position+" expected="+entry.transform.position+" controls="+W.CanControl);}yield break;}
  if(mode=="sceneState"){yield return State(g,check,audit);yield break;}
  foreach(var room in catalog.rooms){long cash=g.economy.Cash;var age=g.growth.Age;var day=g.clock.Day;var time=g.clock.SubDaySeconds;yield return Go(room.roomId,check);var w=W;check(w.objects.All(o=>o.zone==room.roomId),"Only current room interactables exist "+room.roomId);check(UnityEngine.Object.FindObjectsByType<GameManager>(FindObjectsSortMode.None).Length==1&&UnityEngine.Object.FindObjectsByType<WorldPlayerMotor>(FindObjectsSortMode.None).Length==1,"Single shared manager and one physical player "+room.roomId);check(g.economy.Cash==cash&&g.growth.Age==age&&g.clock.Day==day&&Math.Abs(g.clock.SubDaySeconds-time)<1,"Money / age / time survive room load "+room.roomId);check(SceneManager.sceneCount==1,"Previous room unloaded; only current loaded room plus DontDestroy managers remain "+room.roomId);var s=w.GetComponent<WorldNPCScheduler>();check(s.sceneScoped&&s.actors.All(a=>a.zone==room.roomId)&&s.actors.Select(a=>a.npcId).Distinct().Count()==s.actors.Length,"Local resident instances are unique "+room.roomId);audit(w.hud.gameObject,room.sceneName+" HUD");w.hud.Notify("",0);yield return null;yield return Shot(room.sceneName);}
  check(g.world.State.residents.Count==catalog.rules.npcs.Length,"All resident logical records survive room unloads");
  yield return Go("family-kitchen",check);g.clock.Restore(4,new TimeSnapshot{subDaySeconds=7*3600+60});yield return new WaitForSecondsRealtime(1);check(W.GetComponent<WorldNPCScheduler>().actors.All(a=>a.zone=="family-kitchen"),"Kitchen schedule materializes only kitchen residents");check(!T.NavigateRoom("unregistered-room",Vector2.zero,Vector2.down)&&W.Room.roomId=="family-kitchen"&&!T.IsTransitioning,"Invalid destination preserves room and restores transition state");
  var save=g.CaptureState();check((bool)typeof(SaveManager).GetMethod("Valid",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{save}),"Room IDs remain valid save data");
 }
 public static IEnumerator Meal(GameManager g,Action<bool,string> check){g.growth.Restore(new ProgressSnapshot{age=19});g.clock.realtimeEnabled=false;g.clock.Restore(4,new TimeSnapshot{subDaySeconds=7*3600+40*60});yield return Go("family-kitchen",check);var table=W.GetComponentInChildren<FamilySharedDiningPresentation>();W.Player.Warp(W.CurrentZone.origin+new Vector2(3.9f,-2.8f));float until=Time.unscaledTime+25;while(table.Mask!=3&&Time.unscaledTime<until)yield return null;check(table.Mask==3,"Two actual parents occupy distinct seats in the separate kitchen scene");var seat=W.objects.Single(o=>o.id=="family-player-seat");W.Player.Warp(seat.Point);var stats=g.stats.Capture();stats.hunger=40;g.stats.Restore(stats);yield return null;int food=FamilyLife.State(g).meals;check(W.Begin(seat,3),"Player joins one real family table in separate kitchen");var seen=new System.Collections.Generic.HashSet<int>();while(W.Busy){if(table.Mask==7){seen.Add(table.Frame);if(seen.Count==2){W.hud.Notify("",0);yield return Shot("Final-Family-Meal");}}yield return null;}check(seen.Count>=3&&FamilyLife.State(g).meals==food-1&&g.stats.Hunger>40&&W.CanControl,"Three family eating frames consume food, restore hunger and release control");}
 public static IEnumerator CaptureRooms(GameManager g,Action<bool,string> check){g.growth.Restore(new ProgressSnapshot{age=19});g.clock.realtimeEnabled=false;foreach(var room in T.roomCatalog.rooms.Where(r=>r.family)){yield return Go(room.roomId,check);check(!W.GetComponentsInChildren<TMPro.TMP_Text>().Any(t=>t.name.StartsWith("Destination label / ")),"No redundant destination text beneath shared HUD "+room.roomId);W.hud.Notify("",0);yield return new WaitForSecondsRealtime(.2f);yield return Shot("Final-"+room.sceneName);}}
 public static IEnumerator Final(GameManager g,Action<bool,string> check,Action<GameObject,string> audit){
  yield return Shot("Final-Newborn-Nursery");g.growth.Restore(new ProgressSnapshot{age=19});g.clock.realtimeEnabled=false;g.clock.Restore(4,new TimeSnapshot{subDaySeconds=14*3600});var cash=g.stats.Capture();cash.money=1000;g.stats.Restore(cash);check(g.economy.MoveResidence("qa-final-home","starter"),"Final room audit uses paid qualified independence");
  foreach(var r in T.roomCatalog.rooms){yield return Go(r.roomId,check);var bindings=UnityEngine.Object.FindAnyObjectByType<GameplaySceneBindings>();check(bindings!=null&&bindings.hud.game==g&&bindings.missionUI.service==g.missions,"Actual UI and mission bindings retained "+r.roomId);if(r.family){var floor=W.GetComponentsInChildren<SpriteRenderer>().Single(s=>s.name=="Room owned floor");var back=W.GetComponentsInChildren<SpriteRenderer>().Single(s=>s.name=="Room owned rear wallpaper");check(back.bounds.min.y<=floor.bounds.max.y+.01f,"Wall bottom pivot joins floor without gap "+r.roomId);}W.hud.Notify("",0);yield return new WaitForSecondsRealtime(.2f);audit(W.hud.gameObject,r.sceneName+"final1280");yield return Shot("Final-"+r.sceneName);}
  yield return Go("family-ian-bedroom",check);var bed=W.objects.Single(o=>o.id=="family-bed");W.Player.Warp(bed.Point);yield return null;var ui=UnityEngine.Object.FindAnyObjectByType<UIManager>();int day=g.clock.Day;double seconds=g.clock.SubDaySeconds;ui.sleepButton.onClick.Invoke();check(W.Busy,"Restored actual UI sleep button invokes original bed action");yield return Wait();check(g.clock.Day>day||g.clock.SubDaySeconds>seconds,"UI bed action commits real sleep time and restores controls");var missions=UnityEngine.Object.FindAnyObjectByType<MissionUI>();missions.listButton.onClick.Invoke();yield return null;check(missions.listPanel.activeInHierarchy&&missions.service==g.missions,"Real mission list button remains wired after split");while(W.hud.shell.Depth>0)W.hud.shell.Pop();
  CommercialSliceVerification.SetSize(1920,1080);yield return new WaitForSecondsRealtime(.3f);audit(W.hud.gameObject,"Room HUD1920");yield return Shot("Final-IanRoom-1920");CommercialSliceVerification.SetSize(1280,720);
  yield return Go("city",check);g.NewGame();yield return null;yield return Wait();var birth=UnityEngine.Object.FindAnyObjectByType<BirthIntroductionPopup>();check(W.Room.roomId=="family-ian-bedroom"&&g.growth.Age==0&&g.economy.Cash==0&&g.economy.Debt==1000000,"Actual new game from city returns to nursery with correct newborn state");check(birth.IsShowing&&!W.Player.MovementAllowed&&W.IsInReach(W.objects.Single(o=>o.id=="family-bed")),"Repeated new-life birth popup and reachable caregiver bed remain functional");yield return new WaitForSecondsRealtime(.2f);yield return Shot("Final-NewGame-From-City");birth.begin.onClick.Invoke();yield return null;check(!g.BirthIntroductionPending,"New-game scene transition restores birth confirmation controls");
 }
 public static IEnumerator Housing(GameManager g,Action<bool,string> check,Action<GameObject,string> audit){
  var t=T;g.clock.realtimeEnabled=false;g.growth.Restore(new ProgressSnapshot{age=7});yield return Go("alley",check);var privateDoor=W.objects.Single(o=>o.id=="house-entrance");check(!privateDoor.gameObject.activeInHierarchy&&!W.Use(privateDoor)&&!t.NavigateRoom("home",Vector2.zero,Vector2.down),"Family resident cannot see or use unowned personal-home entrance");check(W.objects.Single(o=>o.id=="family-front").gameObject.activeInHierarchy,"Real family-home entrance remains available");var access=W.GetComponent<ResidentialEntrancePresentation>();check(access.personalEntranceObjects.Length==3&&access.personalEntranceObjects.All(o=>!o.activeSelf),"Personal door and both personal-house signs hidden together");g.growth.Restore(new ProgressSnapshot{age=18});check(!g.economy.CanMoveResidence("starter",out _),"Independence remains locked at18");g.growth.Restore(new ProgressSnapshot{age=19});check(FamilyLife.AtFamily(g)&&!privateDoor.gameObject.activeSelf,"Age19 alone does not expose personal home");var funded=g.stats.Capture();funded.money=1000;g.stats.Restore(funded);check(g.economy.MoveResidence("qa/residential-move","starter")&&g.economy.Cash==500,"Actual existing500G independence transaction");check(privateDoor.gameObject.activeSelf&&new ResidenceAccess(g).IsOwned,"Paid independence activates the same world doorway");
  foreach(string id in new[]{"family-living","family-kitchen","family-parents-bedroom","family-ian-bedroom","family-bathroom","home","bathroom"}){yield return Go(id,check);check(W.transform.rotation==Quaternion.identity&&W.follow.target.orthographic,"Room root grid is level with orthographic camera "+id);if(id.StartsWith("family-")){var z=W.CurrentZone;check(z.size.x*z.size.y<(id=="family-living"||id=="family-kitchen"?80:50),"Functional compact room area "+id);check(W.GetComponentsInChildren<BoxCollider2D>().Any(c=>c.name=="West wall")&&W.GetComponentsInChildren<SpriteRenderer>().Any(r=>r.name=="West wall visible"),"Physical and visible side walls share boundaries "+id);}W.hud.Notify("",0);yield return new WaitForSecondsRealtime(.15f);audit(W.hud.gameObject,id+"1280");yield return Shot("Residential-"+id);}
  yield return Go("family-bathroom",check);check(W.GetComponentsInChildren<SpriteRenderer>().Any(s=>s.name=="Family laundry and towels")&&W.CurrentZone.size.x*W.CurrentZone.size.y<25,"Family bathroom reduced to24 square world units with towels and mat");
  foreach(var edge in t.roomCatalog.portals.Where(p=>p.sourceRoom.StartsWith("family-")||p.doorId=="family-front")){yield return Go(edge.sourceRoom,check);var o=W.objects.Single(o=>o.id==edge.doorId);var d=o.GetComponent<WorldDoor>();W.Player.Warp(d.Approach(d.Plane-d.normal));yield return null;check(W.Use(o)&&!W.Use(o),"Resized room door / duplicate input "+edge.doorId);yield return Wait();var entry=W.GetComponentsInChildren<RoomEntryPoint>().Single(p=>p.entryId==edge.destinationEntryId);check(W.Room.roomId==edge.destinationRoom&&W.CanControl&&Vector2.Distance(W.Player.Position,entry.transform.position)<.3f,"Resized room threshold and destination anchor "+edge.doorId);}
  yield return Go("family-kitchen",check);yield return State(g,check,audit);
 }
 static IEnumerator State(GameManager g,Action<bool,string> check,Action<GameObject,string> audit){
  yield return Go("home",check);var funded=g.stats.Capture();funded.money=1000000;g.stats.Restore(funded);var mission=JsonUtility.ToJson(g.missions.Capture());var career=JsonUtility.ToJson(g.phase23.Capture());
  check(g.economy.BuyFurniture("scene/buy-fridge","fridge"),"Real wallet purchase in separate personal home");check(g.economy.FindFurniturePlacement("fridge",false,out var place,out var why)&&g.economy.PlaceFurniture("fridge",place),"Real collision-checked furniture placement / "+why);var installed=g.economy.Housing.placed.Single(p=>p.id=="fridge");check(installed.homeId=="player"&&installed.roomId=="home"&&installed.ownership=="player"&&installed.installed,"Furniture save carries HomeId RoomId ownership and installation");long cash=g.economy.Cash;g.Save();var missions=JsonUtility.ToJson(g.missions.Capture());var economy=JsonUtility.ToJson(g.economy.Housing);long debt=g.economy.Debt;
  yield return Go("city",check);check(!g.economy.PlaceFurniture("fridge",place),"Cannot accidentally place personal furniture into City");var zero=g.stats.Capture();zero.money=0;g.stats.Restore(zero);g.Load();yield return null;yield return Wait();check(W.Room.roomId=="home"&&g.economy.Cash==cash,"Actual disk load automatically returns to saved physical room with cash intact");check(JsonUtility.ToJson(g.economy.Housing)==economy&&g.economy.Debt==debt&&JsonUtility.ToJson(g.missions.Capture())==missions&&JsonUtility.ToJson(g.phase23.Capture())==career,"Save/load preserves furniture debt investment missions career and relationships");check(W.furnishingRoot.GetComponentsInChildren<WorldInteractable>().Any(o=>o.id=="fridge"),"Bought fridge materializes after leaving and loading room");
  yield return Go("family-kitchen",check);check(W.furnishingRoot.childCount==0,"Personal fridge is never generated into family kitchen");W.hud.Notify("",0);yield return new WaitForSecondsRealtime(.3f);yield return Shot("Kitchen-Material-After");
  // Observe real local walking and animations, rather than only schedule records.
  g.clock.Restore(4,new TimeSnapshot{subDaySeconds=7*3600+60});float end=Time.unscaledTime+30;while(FamilyLife.State(g).ingredientCarrier!="family-mother"&&Time.unscaledTime<end)yield return null;check(FamilyLife.State(g).ingredientCarrier=="family-mother","Mother enters loaded kitchen and actually takes refrigerator ingredients");
  g.clock.Restore(4,new TimeSnapshot{subDaySeconds=7*3600+11*60});end=Time.unscaledTime+18;while(FamilyLife.State(g).preparedMeals!=3&&Time.unscaledTime<end)yield return null;check(FamilyLife.State(g).preparedMeals==3,"Visible local cooking reaches actual family food commit");yield return Shot("Kitchen-Cooking");
  g.clock.Restore(4,new TimeSnapshot{subDaySeconds=7*3600+31*60});end=Time.unscaledTime+18;while(FamilyLife.State(g).preparedMeals!=0&&Time.unscaledTime<end)yield return null;check(FamilyLife.State(g).preparedMeals==0,"Cooked meals served in shared kitchen scene");
  yield return Go("family-living",check);g.clock.Restore(4,new TimeSnapshot{subDaySeconds=12*3600+60});g.world.AdvanceAbsentResidents();check(FamilyLife.State(g).ingredientCarrier=="family-father","Offscreen kitchen uses shared logical family action receipts");int pantry=FamilyLife.State(g).pantry;g.world.AdvanceAbsentResidents();check(FamilyLife.State(g).pantry==pantry,"Offscreen repeated same-minute update cannot duplicate consumption");
  yield return AdvancedWorldVerification.Mobile(W,g,check,audit);yield return Go("workplace",check);yield return new WaitForSecondsRealtime(1);check(W.GetComponentsInChildren<WorldWorkstationPresentation>().Length==5,"Existing company five authored workstations retained");yield return Shot("Workspace-Preserved");
 }
}
}
